import { relations } from 'drizzle-orm'
import {
  boolean,
  index,
  integer,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uuid,
} from 'drizzle-orm/pg-core'
import { user } from './auth-schema.gen'

// auth-schema is generated by @better-auth/cli when running generate (Better Auth speaks Drizzle)
export * from './auth-schema.gen'

// Aligned to specs/payments.allium Subscription entity.
// One row per user (enforced by userId UNIQUE). Cascade delete covers the
// CascadeUserDeletionToSubscription rule. Provider ID is opaque — Stripe
// subscription id / Apple IAP transaction id — and null in tests.
export const subscription = pgTable('subscription', {
  id: uuid('id')
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  userId: text('user_id')
    .notNull()
    .unique()
    .references(() => user.id, { onDelete: 'cascade' }),
  interval: text('interval', { enum: ['monthly'] })
    .notNull()
    .default('monthly'),
  status: text('status', { enum: ['active', 'grace', 'cancelled', 'lapsed'] }).notNull(),
  startedAt: timestamp('started_at').notNull(),
  currentPeriodEnd: timestamp('current_period_end').notNull(),
  cancelledAt: timestamp('cancelled_at'),
  lapsedAt: timestamp('lapsed_at'),
  graceStartedAt: timestamp('grace_started_at'),
  graceEndsAt: timestamp('grace_ends_at'),
  providerRef: text('provider_ref'),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  updatedAt: timestamp('updated_at')
    .$onUpdate(() => new Date())
    .notNull()
    .defaultNow(),
})

// Aligned to specs/wardrobe.allium WardrobeItem.
export const clothingItem = pgTable('clothing_item', {
  id: uuid('id')
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  userId: text('user_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  imageUrl: text('image_url').notNull(),
  category: text('category', {
    enum: [
      'tee',
      'collared_shirt',
      'outer',
      'pants',
      'shorts',
      'headwear',
      'footwear',
      'bag',
      'scarf',
      'accessory',
      'dress',
      'skirt',
    ],
  }).notNull(),
  primaryColor: text('primary_color').notNull(),
  secondaryColor: text('secondary_color'),
  materials: text('materials').array().notNull().default([]),
  brand: text('brand'),
  fit: text('fit', { enum: ['tight', 'slim', 'standard', 'relaxed', 'oversize'] }),
  pattern: text('pattern'),
  occasions: text('occasions').array().notNull().default([]),
  customNotes: text('custom_notes'),
  isFavorite: boolean('is_favorite').notNull().default(false),
  status: text('status', { enum: ['active', 'archived', 'removed'] })
    .notNull()
    .default('active'),
  archivedAt: timestamp('archived_at'),
  removedAt: timestamp('removed_at'),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  updatedAt: timestamp('updated_at')
    .$onUpdate(() => new Date())
    .notNull()
    .defaultNow(),
})

// Aligned to specs/wardrobe.allium Outfit entity.
export const outfit = pgTable(
  'outfit',
  {
    id: uuid('id')
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    name: text('name'),
    // Slot FKs: ON DELETE SET NULL so the outfit survives item deletion but
    // loses the slot — matches spec RemoveItemPreservingOutfits semantics.
    headwearId: uuid('headwear_id').references(() => clothingItem.id, { onDelete: 'set null' }),
    baseId: uuid('base_id').references(() => clothingItem.id, { onDelete: 'set null' }),
    outerId: uuid('outer_id').references(() => clothingItem.id, { onDelete: 'set null' }),
    bottomId: uuid('bottom_id').references(() => clothingItem.id, { onDelete: 'set null' }),
    footwearId: uuid('footwear_id').references(() => clothingItem.id, { onDelete: 'set null' }),
    tags: text('tags').array().notNull().default([]),
    notes: text('notes'),
    rating: text('rating', { enum: ['loved', 'ok', 'didnt_work'] }),
    wornAt: timestamp('worn_at'),
    status: text('status', { enum: ['active', 'deleted'] })
      .notNull()
      .default('active'),
    deletedAt: timestamp('deleted_at'),
    createdAt: timestamp('created_at').notNull().defaultNow(),
    updatedAt: timestamp('updated_at')
      .$onUpdate(() => new Date())
      .notNull()
      .defaultNow(),
  },
  (t) => [
    index('outfit_user_id_idx').on(t.userId),
    index('outfit_headwear_id_idx').on(t.headwearId),
    index('outfit_base_id_idx').on(t.baseId),
    index('outfit_outer_id_idx').on(t.outerId),
    index('outfit_bottom_id_idx').on(t.bottomId),
    index('outfit_footwear_id_idx').on(t.footwearId),
  ],
)

// Aligned to specs/onboarding.allium OnboardingProgress entity. One row per
// user (enforced by userId as PK). Auto-created on user signup via
// databaseHooks.user.create.after in backend/auth.ts.
export const onboardingProgress = pgTable('onboarding_progress', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  status: text('status', { enum: ['in_progress', 'completed'] })
    .notNull()
    .default('in_progress'),
  biometricsCompletedAt: timestamp('biometrics_completed_at'),
  starterWardrobeCompletedAt: timestamp('starter_wardrobe_completed_at'),
  startedAt: timestamp('started_at').notNull().defaultNow(),
  completedAt: timestamp('completed_at'),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  updatedAt: timestamp('updated_at')
    .$onUpdate(() => new Date())
    .notNull()
    .defaultNow(),
})

// Aligned to specs/fit-page.allium UserBiometrics entity. One row per user
// (enforced by userId as PK).
export const userBiometrics = pgTable('user_biometrics', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  heightCm: integer('height_cm').notNull(),
  weightKg: integer('weight_kg').notNull(),
  facePhotoUrl: text('face_photo_url'),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  updatedAt: timestamp('updated_at')
    .$onUpdate(() => new Date())
    .notNull()
    .defaultNow(),
})

// Aligned to specs/style-board.allium StyleTag entity. Labels are unique so
// curators don't duplicate categories.
export const styleTag = pgTable('style_tag', {
  id: uuid('id')
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  label: text('label').notNull().unique(),
  category: text('category', {
    enum: ['aesthetic', 'color', 'silhouette', 'occasion', 'season'],
  }).notNull(),
  createdAt: timestamp('created_at').notNull().defaultNow(),
})

// Aligned to specs/style-board.allium StyleCard entity. Retirement is a soft
// status change (status='retired', retiredAt set) so that SavedStyle rows
// referencing the card can still be read — per spec decision, saves persist
// after retirement.
export const styleCard = pgTable('style_card', {
  id: uuid('id')
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  imageUrl: text('image_url').notNull(),
  sourceAttribution: text('source_attribution').notNull(),
  status: text('status', { enum: ['active', 'retired'] })
    .notNull()
    .default('active'),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  retiredAt: timestamp('retired_at'),
})

// Join: StyleCard -> StyleTag. Composite PK (cardId, tagId).
export const styleCardTag = pgTable(
  'style_card_tag',
  {
    cardId: uuid('card_id')
      .notNull()
      .references(() => styleCard.id, { onDelete: 'cascade' }),
    tagId: uuid('tag_id')
      .notNull()
      .references(() => styleTag.id, { onDelete: 'cascade' }),
  },
  (t) => [primaryKey({ columns: [t.cardId, t.tagId] })],
)

// StyleInteraction — permanent record of a user's like/skip on a card.
// AtMostOneInteractionPerUserCard invariant is enforced at the handler layer
// (we check before inserting); the index makes the lookup cheap.
export const styleInteraction = pgTable(
  'style_interaction',
  {
    id: uuid('id')
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    cardId: uuid('card_id')
      .notNull()
      .references(() => styleCard.id, { onDelete: 'cascade' }),
    kind: text('kind', { enum: ['liked', 'skipped'] }).notNull(),
    occurredAt: timestamp('occurred_at').notNull().defaultNow(),
  },
  (t) => [
    index('style_interaction_user_card_idx').on(t.userId, t.cardId),
    index('style_interaction_user_kind_idx').on(t.userId, t.kind),
  ],
)

// SavedStyle — an entry in the user's personal style board. Unique on
// (userId, cardId) — can't save the same card twice. Retiring the card does
// NOT delete the SavedStyle (retirement is a status change, not a row delete).
export const savedStyle = pgTable(
  'saved_style',
  {
    id: uuid('id')
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    cardId: uuid('card_id')
      .notNull()
      .references(() => styleCard.id, { onDelete: 'cascade' }),
    savedAt: timestamp('saved_at').notNull().defaultNow(),
  },
  (t) => [unique('saved_style_user_card_unique').on(t.userId, t.cardId)],
)

// Aligned to specs/fit-page.allium FitAdjustment entity (lines 81-90).
// Per-(user, item) sizing note. Unique on (userId, itemId) — one adjustment
// per user/item pair (OneFitAdjustmentPerUserItem invariant, lines 272-276).
// Enum values mirror the spec exactly.
export const fitAdjustment = pgTable(
  'fit_adjustment',
  {
    id: uuid('id')
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    itemId: uuid('item_id')
      .notNull()
      .references(() => clothingItem.id, { onDelete: 'cascade' }),
    length: text('length', { enum: ['shorter', 'true_to_size', 'longer'] }),
    width: text('width', { enum: ['tighter', 'true_to_size', 'looser'] }),
    sleeve: text('sleeve', { enum: ['too_short', 'true_to_size', 'too_long'] }),
    rise: text('rise', { enum: ['low_rise', 'mid_rise', 'high_rise'] }),
    customNotes: text('custom_notes'),
    createdAt: timestamp('created_at').notNull().defaultNow(),
    updatedAt: timestamp('updated_at')
      .$onUpdate(() => new Date())
      .notNull()
      .defaultNow(),
  },
  (t) => [unique('fit_adjustment_user_item_unique').on(t.userId, t.itemId)],
)

// Aligned to specs/fit-page.allium SharedOutfit entity (lines 92-106).
//
// Singleton per Outfit (invariant OneSharedOutfitPerOutfit, lines 283-287):
// unique on outfitId. Decision re: the spec's open question (line 381) — we
// treat SharedOutfit as a singleton per Outfit. Re-publishing an already
// unpublished SharedOutfit transitions it back to 'published' and updates
// anonymisation/showUsername in place (see PublishOutfit handler).
export const sharedOutfit = pgTable(
  'shared_outfit',
  {
    id: uuid('id')
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    outfitId: uuid('outfit_id')
      .notNull()
      .unique()
      .references(() => outfit.id, { onDelete: 'cascade' }),
    faceAnonymisation: text('face_anonymisation', {
      enum: ['none', 'blur_face', 'block_eyes'],
    }).notNull(),
    showUsername: boolean('show_username').notNull(),
    status: text('status', { enum: ['published', 'unpublished'] })
      .notNull()
      .default('published'),
    sharedAt: timestamp('shared_at').notNull().defaultNow(),
    unpublishedAt: timestamp('unpublished_at'),
    createdAt: timestamp('created_at').notNull().defaultNow(),
    updatedAt: timestamp('updated_at')
      .$onUpdate(() => new Date())
      .notNull()
      .defaultNow(),
  },
  (t) => [index('shared_outfit_status_idx').on(t.status, t.sharedAt)],
)

// Aligned to specs/fit-page.allium OutfitRecommendationRequest (lines 108-112)
// and RequestRecommendations rule (lines 227-244). A lightweight request
// record — the recommendation engine itself is deferred (see spec lines
// 300-302 and recommendation handler). Status machine mirrors a typical
// job queue: pending -> computed | failed. A background worker would
// transition rows; the handler here only writes 'pending'.
export const outfitRecommendationRequest = pgTable(
  'outfit_recommendation_request',
  {
    id: uuid('id')
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    kind: text('kind', { enum: ['gap_filling', 'outfit_generation'] }).notNull(),
    basedOnOutfitId: uuid('based_on_outfit_id').references(() => outfit.id, {
      onDelete: 'cascade',
    }),
    status: text('status', { enum: ['pending', 'computed', 'failed'] })
      .notNull()
      .default('pending'),
    requestedAt: timestamp('requested_at').notNull().defaultNow(),
    computedAt: timestamp('computed_at'),
    createdAt: timestamp('created_at').notNull().defaultNow(),
    updatedAt: timestamp('updated_at')
      .$onUpdate(() => new Date())
      .notNull()
      .defaultNow(),
  },
  (t) => [index('outfit_recommendation_user_idx').on(t.userId, t.requestedAt)],
)

// Aligned to specs/social-share.allium ShareableCard entity (lines 59-97).
// Modelled as a single table with a `kind` discriminator — the three variants
// (OutfitCard, WardrobeShowcaseCard, StyleStatsCard) share all common columns
// (owner, theme, caption, status, created_at, expiresAt) and only differ in a
// handful of nullable variant-specific columns (outfitId, showcaseMode,
// statsPeriod). Filter/mode-filter fields from the WardrobeShowcaseCard
// variant are elided at this iteration — handlers accept the showcaseMode but
// do not yet persist the category/color/style filter (future work).
//
// expiresAt is precomputed on create from config.card_ttl (90 days per spec).
// Expiry is a status transition (live -> expired) performed by a cron handler.
export const shareableCard = pgTable(
  'shareable_card',
  {
    id: uuid('id')
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    kind: text('kind', { enum: ['outfit', 'wardrobe_showcase', 'style_stats'] }).notNull(),
    caption: text('caption'),
    theme: text('theme', { enum: ['light', 'dark', 'colorful'] }).notNull(),
    renderedImageUrl: text('rendered_image_url').notNull(),
    status: text('status', { enum: ['active', 'expired'] })
      .notNull()
      .default('active'),
    createdAt: timestamp('created_at').notNull().defaultNow(),
    expiresAt: timestamp('expires_at').notNull(),
    // Variant-specific nullables (only one set per row per `kind`).
    outfitId: uuid('outfit_id').references(() => outfit.id, { onDelete: 'cascade' }),
    showcaseMode: text('showcase_mode', {
      enum: ['by_category', 'by_color', 'by_style', 'entire_wardrobe'],
    }),
    statsPeriod: text('stats_period', { enum: ['week', 'month', 'year'] }),
  },
  (t) => [index('shareable_card_user_created_idx').on(t.userId, t.createdAt)],
)

// ShareEvent — one row per (card, platform) post. userId is intentionally NOT
// stored; derivable via card.userId. Kept per the spec-aligned decision to
// normalize the sharer off the event.
export const shareEvent = pgTable(
  'share_event',
  {
    id: uuid('id')
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    cardId: uuid('card_id')
      .notNull()
      .references(() => shareableCard.id, { onDelete: 'cascade' }),
    platform: text('platform', {
      enum: ['instagram_story', 'snapchat', 'tiktok', 'twitter', 'clipboard'],
    }).notNull(),
    occurredAt: timestamp('occurred_at').notNull().defaultNow(),
  },
  (t) => [index('share_event_card_idx').on(t.cardId)],
)

// ShareClick — inbound click from a shared link. referredUserId is nullable
// and set later by AttributeClickToSignup (helper). ON DELETE SET NULL so
// when a referred user deletes their account, we keep the anonymous click
// count but drop the attribution (per spec decision lines 243-257).
export const shareClick = pgTable(
  'share_click',
  {
    id: uuid('id')
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    cardId: uuid('card_id')
      .notNull()
      .references(() => shareableCard.id, { onDelete: 'cascade' }),
    platform: text('platform', {
      enum: ['instagram_story', 'snapchat', 'tiktok', 'twitter', 'clipboard'],
    }).notNull(),
    referredUserId: text('referred_user_id').references(() => user.id, {
      onDelete: 'set null',
    }),
    occurredAt: timestamp('occurred_at').notNull().defaultNow(),
  },
  (t) => [index('share_click_card_idx').on(t.cardId)],
)

export const styleCardRelations = relations(styleCard, ({ many }) => ({
  tags: many(styleCardTag),
}))

export const styleTagRelations = relations(styleTag, ({ many }) => ({
  cards: many(styleCardTag),
}))

export const styleCardTagRelations = relations(styleCardTag, ({ one }) => ({
  card: one(styleCard, { fields: [styleCardTag.cardId], references: [styleCard.id] }),
  tag: one(styleTag, { fields: [styleCardTag.tagId], references: [styleTag.id] }),
}))

export const outfitRelations = relations(outfit, ({ one }) => ({
  owner: one(user, { fields: [outfit.userId], references: [user.id] }),
  headwear: one(clothingItem, {
    fields: [outfit.headwearId],
    references: [clothingItem.id],
    relationName: 'outfit_headwear',
  }),
  base: one(clothingItem, {
    fields: [outfit.baseId],
    references: [clothingItem.id],
    relationName: 'outfit_base',
  }),
  outer: one(clothingItem, {
    fields: [outfit.outerId],
    references: [clothingItem.id],
    relationName: 'outfit_outer',
  }),
  bottom: one(clothingItem, {
    fields: [outfit.bottomId],
    references: [clothingItem.id],
    relationName: 'outfit_bottom',
  }),
  footwear: one(clothingItem, {
    fields: [outfit.footwearId],
    references: [clothingItem.id],
    relationName: 'outfit_footwear',
  }),
}))
